import{c as s,$ as e,Q as l,j as n,o as a,m as d,g as h}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuChat 插件介绍","description":"","frontmatter":{"title":"YuChat 插件介绍"},"headers":[],"relativePath":"plugins/items/yu-chat/index.md","filePath":"plugins/items/yu-chat/index.md"}'),u={name:"plugins/items/yu-chat/index.md"},p={class:"quick-actions"};function m(P,t,g,f,y,_){const o=e("PluginMeta"),r=e("CopyMarkdownButton"),c=e("CopyLLMButton"),i=e("PluginServerShowcase");return l(),n("div",null,[a(o,{slug:"yu-chat"}),t[0]||(t[0]=d('<h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to &quot;文档入口&quot;">​</a></h2><p>YuChat 是面向 Minecraft <code>1.8.x-1.26.x</code> 的跨版本聊天称呼与昵称插件，环境适配范围与 YuTeleport 保持一致：Spigot、Paper、Paper 衍生端，以及 Mohist、Arclight、Youer 等 Bukkit API 混合端。它把玩家称呼、昵称、个性签名、自定义死亡消息、LuckPerms 前后缀、PlaceholderAPI 变量、经济购买、GUI 管理和 TAB/头顶名同步整合到一个聊天显示插件里，适合生存服、RPG 服、会员体系服务器和需要细致身份展示的社区服。</p><div class="doc-card-grid"><a class="doc-mini-card" href="install"><strong>安装部署</strong><span>免费版获取、高级版赞助、放置 jar、首次启动、运行库下载和上线检查</span></a><a class="doc-mini-card" href="commands"><strong>命令手册</strong><span>/yuchat、/yc、/chat 的 GUI、昵称、签名、死亡消息、管理和重载命令</span></a><a class="doc-mini-card" href="config"><strong>配置说明</strong><span>数据库、聊天格式、悬浮消息、经济、昵称、显示同步、声音和公告</span></a><a class="doc-mini-card" href="permissions"><strong>权限节点</strong><span>基础使用、颜色解析、格式权限、称呼权限、管理员与重载权限</span></a><a class="doc-mini-card" href="placeholders"><strong>PlaceholderAPI</strong><span>%yuchat_*% 变量、TAB/菜单/计分板接入和 LuckPerms meta 读取</span></a><a class="doc-mini-card" href="api"><strong>插件联动</strong><span>LuckPerms、Vault、PlayerPoints、PlaceholderAPI、TAB、EasyBot 和文件结构</span></a><a class="doc-mini-card" href="faq"><strong>常见问题</strong><span>聊天不显示、PAPI 没值、经济扣费、TAB 覆盖、依赖下载和混合端排查</span></a></div>',3)),h("div",p,[a(r,{slug:"yu-chat"}),a(c,{slug:"yu-chat"})]),t[1]||(t[1]=d('<h2 id="版本获取" tabindex="-1">版本获取 <a class="header-anchor" href="#版本获取" aria-label="Permalink to &quot;版本获取&quot;">​</a></h2><p>YuChat 提供免费版和高级版。免费版 <code>1.0.6</code> 可在 <a href="https://qm.qq.com/q/xiwJYBYdh0" target="_blank" rel="noreferrer">Yu 插件交流群</a> 获取；需要高级版、持续更新或更完整功能时，请在 <a href="https://afdian.com/item/5913558252bc11f1a1e15254001e7c00" target="_blank" rel="noreferrer">爱发电赞助获取</a>。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>广版本与混合端适配</td><td>面向 <code>1.8.x-1.26.x</code>，覆盖 Spigot、Paper、Paper 衍生端，并兼顾 Mohist、Arclight、Youer 等混合端运行环境。</td></tr><tr><td>称呼系统</td><td>支持内置称呼和 <code>custom_titles.yml</code> 自定义称呼，玩家可同时激活多个称呼并按激活顺序显示。</td></tr><tr><td>昵称与格式</td><td>支持昵称唯一校验、黑名单、正则、长度、冷却、昵称颜色、昵称格式和普通玩家颜色权限限制。</td></tr><tr><td>LuckPerms 显示</td><td>可通过 LuckPerms API 读取 prefix、suffix、meta，也可在接口不可用时按配置用 PlaceholderAPI 兜底。</td></tr><tr><td>聊天与悬浮</td><td>支持聊天格式、聊天内容颜色、MiniMessage/Hex 降级、前缀/后缀/昵称/称呼悬浮文本。</td></tr><tr><td>显示同步</td><td>可同步 Bukkit displayName、TAB 列表、scoreboard-team 头顶名，必要时可切换 hologram 头顶名模式。</td></tr><tr><td>个性签名和死亡消息</td><td>玩家可设置个性签名和自定义死亡消息，死亡原因、击杀者和悬浮内容均可配置。</td></tr><tr><td>经济购买</td><td>支持 Vault 金币、PlayerPoints 点券、两者都扣或二选一，用于昵称、签名、死亡消息、颜色和称呼。</td></tr><tr><td>SQLite/MySQL 存储</td><td>单服默认 SQLite；跨服或多子服共享可切换 MySQL，并统一使用表名前缀。</td></tr><tr><td>GUI 管理</td><td>玩家可用 GUI 切换称呼、颜色和显示开关；管理员可在 GUI 中创建称呼、调整经济和 LuckPerms 显示。</td></tr><tr><td>运行时依赖加载</td><td>首次启动会缓存 HikariCP、SQLite JDBC、MySQL JDBC、SLF4J 等依赖到插件目录并校验哈希。</td></tr><tr><td>统计接入</td><td>内置 bStats Bukkit 统计，插件 ID 为 <code>31412</code>。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>在 Yu 插件交流群获取免费版 <code>1.0.6</code>，或通过爱发电赞助获取高级版。</li><li>将 jar 放入服务端 <code>plugins/</code> 目录并启动一次服务器。</li><li>打开 <code>plugins/YuChat/config.yml</code>，确认 <code>storage.type</code>、<code>chat-format.format</code>、<code>prefix-suffix</code> 和 <code>display</code> 配置。</li><li>给普通玩家分配 <code>yuchat.use</code>、<code>yuchat.gui</code>、<code>yuchat.nickname.use</code>，按需要分配称呼、颜色和格式权限。</li><li>玩家使用 <code>/yc</code>、<code>/chat</code> 或 <code>/yuchat</code> 打开主界面，使用 <code>/yc nick &lt;昵称&gt;</code> 快速修改昵称。</li><li>修改配置后执行 <code>/yc reload</code> 重载配置、消息和 GUI。</li></ol><h2 id="适合的服务器" tabindex="-1">适合的服务器 <a class="header-anchor" href="#适合的服务器" aria-label="Permalink to &quot;适合的服务器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐用法</th></tr></thead><tbody><tr><td>生存服</td><td>作为统一聊天格式与昵称插件，配合 LuckPerms 展示权限组前后缀。</td></tr><tr><td>RPG 服</td><td>使用称呼、称呼颜色和个性签名表达职业、阵营、声望或活动身份。</td></tr><tr><td>会员服</td><td>将称呼、昵称颜色、聊天颜色和死亡消息接入 Vault 或 PlayerPoints。</td></tr><tr><td>多子服网络</td><td>使用 MySQL 存储，让大厅、生存、资源服共享玩家聊天显示数据。</td></tr><tr><td>社区服</td><td>通过 GUI 降低玩家自助配置门槛，同时保留管理员后台配置能力。</td></tr></tbody></table><h2 id="当前版本定位" tabindex="-1">当前版本定位 <a class="header-anchor" href="#当前版本定位" aria-label="Permalink to &quot;当前版本定位&quot;">​</a></h2><ul><li>版本获取：免费版 <code>1.0.6</code> 可在 Yu 插件交流群获取；高级版通过爱发电赞助获取</li><li>主类：<code>org.yutay.yuchat.YuChat</code></li><li>主命令：<code>/yuchat</code></li><li>别名：<code>/yc</code>、<code>/chat</code></li><li>Java 目标版本：Java 8</li><li>编译 API：Spigot API <code>1.8.8-R0.1-SNAPSHOT</code></li><li>兼容定位：Minecraft <code>1.8.x-1.26.x</code>，Spigot、Paper、Paper 衍生端、Mohist、Arclight、Youer 等混合端</li><li>存储方式：SQLite、MySQL</li><li>bStats 插件 ID：<code>31412</code></li><li>默认配置版本：<code>config-version: 30</code></li><li>默认消息版本：<code>messages-version: 10</code></li><li>默认 GUI 版本：<code>gui-version: 9</code></li><li>默认称呼版本：<code>titles-version: 4</code></li><li>默认效果版本：<code>effects-version: 3</code></li></ul><h2 id="使用该插件的服务器" tabindex="-1">使用该插件的服务器 <a class="header-anchor" href="#使用该插件的服务器" aria-label="Permalink to &quot;使用该插件的服务器&quot;">​</a></h2>',11)),a(i,{slug:"yu-chat"})])}const S=s(u,[["render",m]]);export{k as __pageData,S as default};
